static std::vector<std::string> SplitCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string current;
    bool quoted = false;
    for (char ch : line) {
        if (ch == '"') {
            quoted = !quoted;
            continue;
        }
        if (ch == ',' && !quoted) {
            fields.push_back(current);
            current.clear();
        } else {
            current.push_back(ch);
        }
    }
    fields.push_back(current);
    return fields;
}

static std::string CsvQuote(const std::string& value) {
    std::string out = "\"";
    for (char ch : value) {
        if (ch == '"') {
            out += "\"\"";
        } else {
            out.push_back(ch);
        }
    }
    out += "\"";
    return out;
}

static float ParseFloatOr(const std::string& value, float fallback) {
    char* end = nullptr;
    errno = 0;
    const float parsed = std::strtof(value.c_str(), &end);
    return end != value.c_str() && errno != ERANGE ? parsed : fallback;
}

static int32_t ParseIntOr(const std::string& value, int32_t fallback) {
    char* end = nullptr;
    errno = 0;
    const long parsed = std::strtol(value.c_str(), &end, 10);
    return end != value.c_str() && errno != ERANGE ? static_cast<int32_t>(parsed) : fallback;
}

static std::vector<ExactSurfaceNonCoverageAuditSample> LoadExactSurfaceNonCoverageAuditSamples(
    const std::filesystem::path& inputPath)
{
    std::vector<ExactSurfaceNonCoverageAuditSample> samples;
    std::ifstream input(inputPath);
    if (!input) {
        spdlog::warn("Exact surface noncoverage audit could not open {}", inputPath.string());
        return samples;
    }
    std::string headerLine;
    if (!std::getline(input, headerLine)) {
        return samples;
    }
    const std::vector<std::string> header = SplitCsvLine(headerLine);
    std::unordered_map<std::string, size_t> column;
    for (size_t i = 0; i < header.size(); ++i) {
        column[header[i]] = i;
    }
    auto get = [&](const std::vector<std::string>& row, const char* name) -> std::string {
        const auto it = column.find(name);
        return it != column.end() && it->second < row.size() ? row[it->second] : std::string();
    };
    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) {
            continue;
        }
        const std::vector<std::string> row = SplitCsvLine(line);
        if (get(row, "likelyCause") != "exact_surface_not_covering_close_mid_side_face") {
            continue;
        }
        ExactSurfaceNonCoverageAuditSample sample;
        sample.frame = static_cast<uint32_t>(std::max(0, ParseIntOr(get(row, "frame"), 0)));
        sample.region = get(row, "region");
        sample.pixelX = ParseIntOr(get(row, "pixelX"), 0);
        sample.pixelY = ParseIntOr(get(row, "pixelY"), 0);
        sample.midDistance = ParseFloatOr(get(row, "distance"), 0.0f);
        sample.midWorld = glm::vec3(
            ParseFloatOr(get(row, "worldX"), 0.0f),
            ParseFloatOr(get(row, "worldY"), 0.0f),
            ParseFloatOr(get(row, "worldZ"), 0.0f));
        samples.push_back(sample);
    }
    return samples;
}

static std::vector<ExactRequestLifecycleAuditTrace> LoadExactRequestLifecycleAuditTraces(
    const std::filesystem::path& inputPath)
{
    std::vector<ExactRequestLifecycleAuditTrace> traces;
    std::ifstream input(inputPath);
    if (!input) {
        spdlog::warn("Exact request lifecycle audit could not open {}", inputPath.string());
        return traces;
    }
    std::string headerLine;
    if (!std::getline(input, headerLine)) {
        return traces;
    }
    const std::vector<std::string> header = SplitCsvLine(headerLine);
    std::unordered_map<std::string, size_t> column;
    for (size_t i = 0; i < header.size(); ++i) {
        column[header[i]] = i;
    }
    auto get = [&](const std::vector<std::string>& row, const char* name) -> std::string {
        const auto it = column.find(name);
        return it != column.end() && it->second < row.size() ? row[it->second] : std::string();
    };

    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) {
            continue;
        }
        const std::vector<std::string> row = SplitCsvLine(line);
        const std::string dominantReason = get(row, "dominantReason");
        if (dominantReason != "exact_brick_not_resident" &&
            dominantReason != "surface_not_extracted_or_unknown" &&
            dominantReason != "surface_extraction_emitted_no_faces" &&
            dominantReason != "gpu_surface_culling_or_upload_missing") {
            continue;
        }
        ExactRequestLifecycleAuditTrace trace;
        trace.sample.frame = static_cast<uint32_t>(std::max(0, ParseIntOr(get(row, "frame"), 0)));
        trace.sample.region = get(row, "region");
        trace.sample.pixelX = ParseIntOr(get(row, "pixelX"), 0);
        trace.sample.pixelY = ParseIntOr(get(row, "pixelY"), 0);
        trace.sample.expectedExactT = ParseFloatOr(get(row, "expectedExactT"), 0.0f);
        trace.sample.expectedWorld = glm::vec3(
            ParseFloatOr(get(row, "expectedExactWorldX"), 0.0f),
            ParseFloatOr(get(row, "expectedExactWorldY"), 0.0f),
            ParseFloatOr(get(row, "expectedExactWorldZ"), 0.0f));
        trace.sample.coord = {
            ParseIntOr(get(row, "auditBrickX"), 0),
            ParseIntOr(get(row, "auditBrickY"), 0),
            ParseIntOr(get(row, "auditBrickZ"), 0)
        };
        traces.push_back(trace);
    }
    return traces;
}

static std::vector<WaterSurfaceLifecycleAuditSample> LoadWaterSurfaceLifecycleAuditSamples(
    const std::filesystem::path& inputPath)
{
    std::vector<WaterSurfaceLifecycleAuditSample> samples;
    std::ifstream input(inputPath);
    if (!input) {
        spdlog::warn("Water surface lifecycle audit could not open {}", inputPath.string());
        return samples;
    }
    std::string headerLine;
    if (!std::getline(input, headerLine)) {
        return samples;
    }
    const std::vector<std::string> header = SplitCsvLine(headerLine);
    std::unordered_map<std::string, size_t> column;
    for (size_t i = 0; i < header.size(); ++i) {
        column[header[i]] = i;
    }
    auto get = [&](const std::vector<std::string>& row, const char* name) -> std::string {
        const auto it = column.find(name);
        return it != column.end() && it->second < row.size() ? row[it->second] : std::string();
    };

    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) {
            continue;
        }
        const std::vector<std::string> row = SplitCsvLine(line);
        if (get(row, "reasonBucket") != "water_should_draw_before_terrain") {
            continue;
        }
        WaterSurfaceLifecycleAuditSample sample;
        sample.requestedFrame = static_cast<uint32_t>(std::max(0, ParseIntOr(get(row, "requestedFrame"), 0)));
        sample.cameraFrame = static_cast<uint32_t>(std::max(0, ParseIntOr(get(row, "cameraFrame"), 0)));
        sample.pixelX = ParseIntOr(get(row, "pixelX"), 0);
        sample.pixelY = ParseIntOr(get(row, "pixelY"), 0);
        sample.selection = get(row, "selection");
        sample.owner = get(row, "owner");
        sample.materialDebug = get(row, "materialDebug");
        sample.faceDebug = get(row, "faceDebug");
        sample.rayTerrainT = ParseFloatOr(get(row, "rayTerrainT"), 0.0f);
        sample.terrainWorld = glm::vec3(
            ParseFloatOr(get(row, "worldX"), 0.0f),
            ParseFloatOr(get(row, "worldY"), 0.0f),
            ParseFloatOr(get(row, "worldZ"), 0.0f));
        sample.waterPlaneT = ParseFloatOr(get(row, "waterPlaneT"), 0.0f);
        sample.waterWorldX = ParseFloatOr(get(row, "waterWorldX"), 0.0f);
        sample.waterWorldZ = ParseFloatOr(get(row, "waterWorldZ"), 0.0f);
        sample.terrainHeightAtWaterPlane = ParseFloatOr(get(row, "terrainHeightAtWaterPlane"), 0.0f);
        sample.waterExpectedAtPlane = ParseIntOr(get(row, "waterExpectedAtPlane"), 0) != 0;
        sample.waterBeforeTerrain = ParseIntOr(get(row, "waterBeforeTerrain"), 0) != 0;
        samples.push_back(sample);
    }
    return samples;
}

static std::string FrameOrBlank(uint64_t frame) {
    if (frame == UINT64_MAX) {
        return "";
    }
    return std::to_string(frame);
}

static glm::vec3 SparseSurfaceFaceNormal(uint32_t direction) {
    switch (direction) {
    case 0u: return glm::vec3(-1.0f, 0.0f, 0.0f);
    case 1u: return glm::vec3(1.0f, 0.0f, 0.0f);
    case 2u: return glm::vec3(0.0f, -1.0f, 0.0f);
    case 3u: return glm::vec3(0.0f, 1.0f, 0.0f);
    case 4u: return glm::vec3(0.0f, 0.0f, -1.0f);
    default: return glm::vec3(0.0f, 0.0f, 1.0f);
    }
}

static glm::vec3 SparseSurfaceFaceCenter(const Simulation::SparseSurfaceFace& face) {
    const uint32_t direction = Simulation::SparseSurfacePayloadDirection(face.payload);
    const float x0 = static_cast<float>(face.worldX);
    const float y0 = static_cast<float>(face.worldY);
    const float z0 = static_cast<float>(face.worldZ);
    const float width = static_cast<float>(Simulation::SparseSurfacePayloadWidth(face.payload));
    const float height = static_cast<float>(Simulation::SparseSurfacePayloadHeight(face.payload));
    if (direction == 0u) return glm::vec3(x0, y0 + height * 0.5f, z0 + width * 0.5f);
    if (direction == 1u) return glm::vec3(x0 + 1.0f, y0 + height * 0.5f, z0 + width * 0.5f);
    if (direction == 2u) return glm::vec3(x0 + width * 0.5f, y0, z0 + height * 0.5f);
    if (direction == 3u) return glm::vec3(x0 + width * 0.5f, y0 + 1.0f, z0 + height * 0.5f);
    if (direction == 4u) return glm::vec3(x0 + width * 0.5f, y0 + height * 0.5f, z0);
    return glm::vec3(x0 + width * 0.5f, y0 + height * 0.5f, z0 + 1.0f);
}

static bool RayIntersectsSparseSurfaceFace(
    const glm::vec3& origin,
    const glm::vec3& rayDir,
    const Simulation::SparseSurfaceFace& face,
    float* outT,
    glm::vec3* outHit)
{
    const uint32_t direction = Simulation::SparseSurfacePayloadDirection(face.payload);
    const glm::vec3 normal = SparseSurfaceFaceNormal(direction);
    const glm::vec3 center = SparseSurfaceFaceCenter(face);
    const float denom = glm::dot(rayDir, normal);
    if (std::abs(denom) < 1.0e-5f) {
        return false;
    }
    const float t = glm::dot(center - origin, normal) / denom;
    if (!std::isfinite(t) || t <= 0.0f) {
        return false;
    }
    const glm::vec3 hit = origin + rayDir * t;
    const float x0 = static_cast<float>(face.worldX);
    const float y0 = static_cast<float>(face.worldY);
    const float z0 = static_cast<float>(face.worldZ);
    const float width = static_cast<float>(Simulation::SparseSurfacePayloadWidth(face.payload));
    const float height = static_cast<float>(Simulation::SparseSurfacePayloadHeight(face.payload));
    const float eps = 0.001f;
    bool inside = false;
    if (direction == 0u || direction == 1u) {
        inside = hit.y >= y0 - eps && hit.y <= y0 + height + eps &&
            hit.z >= z0 - eps && hit.z <= z0 + width + eps;
    } else if (direction == 2u || direction == 3u) {
        inside = hit.x >= x0 - eps && hit.x <= x0 + width + eps &&
            hit.z >= z0 - eps && hit.z <= z0 + height + eps;
    } else {
        inside = hit.x >= x0 - eps && hit.x <= x0 + width + eps &&
            hit.y >= y0 - eps && hit.y <= y0 + height + eps;
    }
    if (!inside) {
        return false;
    }
    if (outT) *outT = t;
    if (outHit) *outHit = hit;
    return true;
}

static bool ReadGpuTiming(
    ID3D12Resource* readbackBuffer,
    uint64_t timestampFrequency,
    uint32_t frameIndex,
    GpuTimingStats& stats)
{
    stats = {};
    if (!readbackBuffer || timestampFrequency == 0) {
        return false;
    }

    const uint64_t baseByte = static_cast<uint64_t>(frameIndex) * kGpuTimestampCount * sizeof(uint64_t);
    const D3D12_RANGE readRange{
        static_cast<SIZE_T>(baseByte),
        static_cast<SIZE_T>(baseByte + kGpuTimestampCount * sizeof(uint64_t))
    };

    uint8_t* mapped = nullptr;
    HRESULT hr = readbackBuffer->Map(0, &readRange, reinterpret_cast<void**>(&mapped));
    if (FAILED(hr) || !mapped) {
        return false;
    }

    const uint64_t* timestamps = reinterpret_cast<const uint64_t*>(mapped + baseByte);
    const uint64_t t0 = timestamps[0];
    const uint64_t t1 = timestamps[1];
    const uint64_t t2 = timestamps[2];
    const uint64_t t3 = timestamps[3];
    const uint64_t t4 = timestamps[4];
    const uint64_t t5 = timestamps[5];
    const uint64_t t6 = timestamps[6];

    const D3D12_RANGE writtenRange{0, 0};
    readbackBuffer->Unmap(0, &writtenRange);

    if (t0 == 0 || t1 < t0 || t2 < t1 || t3 < t2 || t4 < t3 || t5 < t4 || t6 < t5) {
        return false;
    }

    const double tickToMs = 1000.0 / static_cast<double>(timestampFrequency);
    stats.valid = true;
    stats.sparseUploadMs = static_cast<double>(t1 - t0) * tickToMs;
    stats.preRenderMs = static_cast<double>(t2 - t1) * tickToMs;
    stats.sparseSurfaceMs = static_cast<double>(t3 - t2) * tickToMs;
    stats.raymarchMs = static_cast<double>(t4 - t3) * tickToMs;
    stats.overlayMs = static_cast<double>(t5 - t4) * tickToMs;
    stats.uiAndReadbackMs = static_cast<double>(t6 - t5) * tickToMs;
    stats.frameMs = static_cast<double>(t6 - t0) * tickToMs;
    return true;
}

