    auto recordExactLifecycleRequest = [&](
        const Simulation::BrickCoord& coord,
        const char* lane,
        Simulation::SparseBrickRequestResult result,
        bool budgetSkipped = false) {
        auto found = exactRequestLifecycleTraceIndices.find(coord);
        if (found == exactRequestLifecycleTraceIndices.end()) {
            return;
        }
        for (size_t traceIndex : found->second) {
            ExactRequestLifecycleAuditTrace& trace = exactRequestLifecycleTraces[traceIndex];
            trace.requestAttempted = true;
            trace.firstRequestFrame = std::min(trace.firstRequestFrame, frameCount);
            const std::string laneName = lane ? lane : "visible";
            if (laneName == "protected") {
                trace.protectedRequest = true;
            } else if (laneName == "collision") {
                trace.collisionRequest = true;
            } else if (laneName == "miss-feedback") {
                trace.missFeedbackRequest = true;
                trace.firstMissFeedbackFrame = std::min(trace.firstMissFeedbackFrame, frameCount);
            } else {
                trace.visibleRequest = true;
            }
            trace.budgetSkipped = trace.budgetSkipped || budgetSkipped;
            if (result == Simulation::SparseBrickRequestResult::Allocated ||
                result == Simulation::SparseBrickRequestResult::AlreadyResident) {
                trace.requestAccepted = true;
            } else if (result == Simulation::SparseBrickRequestResult::Rejected) {
                trace.rejected = true;
            } else if (result == Simulation::SparseBrickRequestResult::SkippedKnownEmpty) {
                trace.skippedEmpty = true;
            }
        }
    };
    auto enforceSparseWalkTerrainParity = [&](const char* phase) {
        if (!enableSparseWalkTerrainParityGuard ||
            !sparseBackendRequested ||
            !sparseVoxelWorldReady ||
            enableBoundaryTest) {
            return;
        }

        const float terrainHeight = sparseVoxelWorld.GetTerrain().HeightAt(
            static_cast<int32_t>(std::floor(cameraPos.x)),
            static_cast<int32_t>(std::floor(cameraPos.z)));
        const float supportHeight = std::max(
            terrainHeight,
            static_cast<float>(Simulation::SEA_LEVEL_Y));
        const float minEyeFromCamera =
            supportHeight + std::max(sparseWalkMinCameraAboveTerrain, playerHeight + 0.25f);
        const float minEyeFromFeet =
            supportHeight + playerHeight + sparseWalkMinFeetAboveTerrain;
        const float minSafeEyeY = std::max(minEyeFromCamera, minEyeFromFeet);

        sparseWalkTerrainHeightLastFrame = terrainHeight;
        sparseWalkCameraAboveTerrainLastFrame = cameraPos.y - supportHeight;
        sparseWalkFeetAboveTerrainLastFrame = cameraPos.y - playerHeight - supportHeight;

        if (cameraPos.y < minSafeEyeY) {
            const float oldEyeY = cameraPos.y;
            cameraPos.y = minSafeEyeY;
            cameraVelocityY = std::max(cameraVelocityY, 0.0f);
            ++sparseWalkTerrainParityCorrectionsLastFrame;
            sparseWalkCameraAboveTerrainLastFrame = cameraPos.y - supportHeight;
            sparseWalkFeetAboveTerrainLastFrame = cameraPos.y - playerHeight - supportHeight;
            spdlog::warn(
                "SPARSE_WALK_TERRAIN_REBASE frame={} phase={} oldEyeY={:.2f} newEyeY={:.2f} terrainH={:.2f} cameraAbove={:.2f} feetAbove={:.2f} pos=({:.2f},{:.2f})",
                frameCount,
                phase,
                oldEyeY,
                cameraPos.y,
                terrainHeight,
                sparseWalkCameraAboveTerrainLastFrame,
                sparseWalkFeetAboveTerrainLastFrame,
                cameraPos.x,
                cameraPos.z);
        }

        const bool cameraInsideTerrain =
            sparseWalkCameraAboveTerrainLastFrame < sparseWalkMinCameraAboveTerrain - 0.001f;
        const bool feetInsideTerrain =
            sparseWalkFeetAboveTerrainLastFrame < sparseWalkMinFeetAboveTerrain - 0.001f;
        if (requireSparseWalkTerrainParity &&
            (cameraInsideTerrain || feetInsideTerrain) &&
            !sparseWalkTerrainParityFailed) {
            sparseWalkTerrainParityFailed = true;
            sparseWalkTerrainParityFailureFrame = frameCount;
            sparseWalkTerrainParityFailureCamera = cameraPos;
            sparseWalkTerrainParityFailureHeight = terrainHeight;
            sparseWalkTerrainParityFailureCameraAbove = sparseWalkCameraAboveTerrainLastFrame;
            sparseWalkTerrainParityFailureFeetAbove = sparseWalkFeetAboveTerrainLastFrame;
            spdlog::error(
                "SPARSE_WALK_TERRAIN_VALIDATION_FAIL frame={} phase={} cam=({:.2f},{:.2f},{:.2f}) terrainH={:.2f} cameraAbove={:.2f} feetAbove={:.2f}",
                frameCount,
                phase,
                cameraPos.x,
                cameraPos.y,
                cameraPos.z,
                terrainHeight,
                sparseWalkCameraAboveTerrainLastFrame,
                sparseWalkFeetAboveTerrainLastFrame);
        }
    };
