            ImGui::Text("Sparse prep req %.2f gen %.2f clip %.2f trim %.2f ms",
                perfSparseRequestPrepMs,
                perfSparseGenerationPrepMs,
                perfSparseClipmapPrepMs,
                perfSparseTrimPrepMs);
